const body = $json.body ?? $json;
const tenant_id = body.tenant_id ?? null;
const contract_id = body.contract_id ?? null;
const lead_id = body.lead_id ?? null;
const canais = body.canais ?? { whatsapp: true, email: true };

if (!tenant_id || !contract_id || !lead_id) {
  throw new Error('tenant_id, contract_id e lead_id sao obrigatorios');
}

const supabaseUrl = $vars.SUPABASE_URL ?? $vars.NEXT_PUBLIC_SUPABASE_URL;
const serviceRole = $vars.SUPABASE_SERVICE_ROLE_KEY;

if (!supabaseUrl) {
  throw new Error('SUPABASE_URL nao configurada');
}

if (!serviceRole) {
  throw new Error('SUPABASE_SERVICE_ROLE_KEY nao configurada');
}

const headers = {
  apikey: serviceRole,
  Authorization: `Bearer ${serviceRole}`,
  'Content-Type': 'application/json'
};

const money = new Intl.NumberFormat('pt-BR', {
  style: 'currency',
  currency: 'BRL'
});

function toNumber(value) {
  const n = Number(String(value ?? '').replace(/[^0-9,.-]/g, '').replace(/\./g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}

function toBRL(value) {
  const n = toNumber(value);
  return n === null ? '' : money.format(n);
}

function extensoSimples(value) {
  const n = toNumber(value);
  if (n === null) return '';
  const milhoes = Math.floor(n / 1000000);
  const restoMilhares = Math.floor((n % 1000000) / 1000);
  const partes = [];
  if (milhoes > 0) partes.push(`${milhoes} ${milhoes === 1 ? 'milhão' : 'milhões'}`);
  if (restoMilhares > 0) partes.push(`${restoMilhares} mil`);
  if (partes.length === 0) return toBRL(n);
  return partes.join(' e ');
}

async function fetchJson(url) {
  const response = await fetch(url, { headers });
  const data = await response.json().catch(() => null);
  return { ok: response.ok, status: response.status, data };
}

const contractQuery = `${supabaseUrl}/rest/v1/contracts?id=eq.${contract_id}&tenant_id=eq.${tenant_id}&select=id,tenant_id,lead_id,lead_name,project_id,imovel_id,broker_id,project_name,corretor_name,title,type,status,value,commission_percentage,commission_amount,signed_at,created_at,updated_at`;
const leadQuery = `${supabaseUrl}/rest/v1/leads?id=eq.${lead_id}&tenant_id=eq.${tenant_id}&select=id,tenant_id,name,email,phone,source,status,score,metadata,created_at,updated_at`;

const contractRes = await fetchJson(contractQuery);
const contracts = Array.isArray(contractRes.data) ? contractRes.data : [];
const contract = contracts[0] ?? null;

if (!contract) {
  throw new Error('Contrato nao encontrado');
}

const leadRes = await fetchJson(leadQuery);
const leads = Array.isArray(leadRes.data) ? leadRes.data : [];
const lead = leads[0] ?? null;

if (!lead) {
  throw new Error('Lead nao encontrado');
}

const imovelId = contract.imovel_id ?? contract.project_id ?? null;
const imovelRes = imovelId
  ? await fetchJson(`${supabaseUrl}/rest/v1/imoveis?id=eq.${imovelId}&tenant_id=eq.${tenant_id}&select=id,id_imovel,titulo_comercial,bairro,valor,metadata,created_at,updated_at`)
  : { data: [] };
const imoveis = Array.isArray(imovelRes.data) ? imovelRes.data : [];
const imovel = imoveis[0] ?? null;

const brokerId = contract.broker_id ?? null;
const brokerRes = brokerId
  ? await fetchJson(`${supabaseUrl}/rest/v1/corretores?id=eq.${brokerId}&tenant_id=eq.${tenant_id}&select=id,name,phone,email,created_at,updated_at`)
  : { data: [] };
const brokers = Array.isArray(brokerRes.data) ? brokerRes.data : [];
const broker = brokers[0] ?? null;

const valorBase = contract.value ?? imovel?.valor ?? 0;
const valorFormatado = toBRL(valorBase);
const comissaoValor = contract.commission_amount ?? (contract.commission_percentage != null ? Number(valorBase) * Number(contract.commission_percentage) / 100 : 0);
const comissaoFormatada = toBRL(comissaoValor);
const valorExtenso = extensoSimples(valorBase);
const comprador = lead.name ?? contract.lead_name ?? '';
const imovelNome = imovel?.titulo_comercial ?? contract.project_name ?? '';
const corretorNome = broker?.name ?? contract.corretor_name ?? '';
const contractTitle = contract.title ?? `Contrato - ${comprador || 'Lead'}`;
const pdfLink = `https://docs.google.com/document/d/${contract.id}/export?format=pdf`;
const docLink = `https://docs.google.com/document/d/${contract.id}/edit?usp=sharing`;
const whatsappMessage = `Segue o contrato em PDF para conferência: ${pdfLink}\n\nBaixe o arquivo, assine digitalmente pelo GOV.br e envie o PDF assinado de volta por aqui.`;
const emailSubject = contractTitle;
const emailMessage = `Segue o contrato em PDF para conferência: ${pdfLink}\n\nBaixe o arquivo, assine digitalmente pelo GOV.br e envie o PDF assinado de volta por aqui.`;

return [{
  json: {
    tenant_id,
    contract_id,
    lead_id,
    canais,
    contract,
    lead,
    imovel,
    broker,
    contract_title: contractTitle,
    pdf_link: pdfLink,
    document_link: docLink,
    comprador,
    imovel_nome: imovelNome,
    corretor_nome: corretorNome,
    valor: valorFormatado,
    comissao: comissaoFormatada,
    valor_extenso: valorExtenso,
    id_imovel: imovel?.id_imovel ?? imovel?.id ?? imovelId ?? '',
    whatsapp_to: lead.phone ?? '',
    email_to: lead.email ?? '',
    whatsapp_message: whatsappMessage,
    email_subject: emailSubject,
    email_message: emailMessage,
    should_whatsapp: Boolean(canais.whatsapp && lead.phone),
    should_email: Boolean(canais.email && lead.email),
    template_doc_id: $vars.CONTRACT_TEMPLATE_DOC_ID ?? '',
    output_folder_id: $vars.CONTRACT_OUTPUT_FOLDER_ID ?? ''
  }
}];
